"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["59862"],{44663(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.obrigatoriedade_legal.vigencia_inicio_obrigatorio","status":422,"titulo":"VigenciaInicio obrigat\xf3rio"},"descricao":{"codigo":"uniplus.selecao.obrigatoriedade_legal.vigencia_inicio_obrigatorio","requisitos":[],"oQueAconteceu":["O campo `vigenciaInicio` n\xe3o veio no corpo da requisi\xe7\xe3o, ou veio nulo. Ele \xe9 a data, sem hora, em\\nque a regra passa a valer, e a regra legal n\xe3o pode ser cadastrada sem ela. Nada \xe9 gravado.","Enquanto o in\xedcio n\xe3o \xe9 informado, o fim da vig\xeancia n\xe3o \xe9 conferido: a rela\xe7\xe3o entre as duas datas\\n([`vigencia_invalida`](/erros/uniplus.selecao.obrigatoriedade_legal.vigencia_invalida)) s\xf3 \xe9 verificada\\nquando h\xe1 in\xedcio. Um valor que n\xe3o \xe9 uma data, como texto em branco, n\xe3o chega a este erro: o corpo\\nn\xe3o pode ser lido e a recusa \xe9 de\\n[requisi\xe7\xe3o malformada](/erros/uniplus.requisicao.malformada), com status 400.","A recusa \xe9 de dom\xednio, com status 422. A resposta lista todas as viola\xe7\xf5es de campo da mesma\\nrequisi\xe7\xe3o em `errors[]`, cada uma com o campo em camelCase, o c\xf3digo e a mensagem; o `code` principal da resposta \xe9\\no da primeira viola\xe7\xe3o, na ordem em que os campos s\xe3o conferidos (tipo de processo, categoria, c\xf3digo\\nda regra, predicado, descri\xe7\xe3o, base legal, ato normativo, portaria interna e vig\xeancia).","A confer\xeancia vem depois da permiss\xe3o para manter obrigatoriedades legais e da leitura do corpo, e\\nantes de qualquer consulta: na atualiza\xe7\xe3o, antes de a regra ser buscada\\n([`nao_encontrada`](/erros/uniplus.selecao.obrigatoriedade_legal.nao_encontrada)); nas duas opera\xe7\xf5es,\\nantes da confer\xeancia do tipo de processo e dos c\xf3digos que o predicado cita."],"comoResolver":["Informe `vigenciaInicio` como data (`AAAA-MM-DD`). Na atualiza\xe7\xe3o, a regra \xe9 substitu\xedda por inteiro:\\nreenvie tamb\xe9m os campos que n\xe3o mudam, porque o que n\xe3o for enviado \xe9 tratado como ausente."],"ondeAparece":["Cadastro de uma obrigatoriedade legal","Atualiza\xe7\xe3o de uma obrigatoriedade legal"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Obrigatoriedade legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);